WITH valid AS (SELECT id, customer_id, account_type, balance, opened_date, status, LENGTH(account_type) AS account_type_length, COALESCE(status, 'DIRECT') AS resolved_status FROM accounts WHERE status IS NOT NULL AND status = 'FROZEN'), with_last AS (SELECT s.id, s.customer_id, s.balance, s.account_type_length, s.resolved_status, latest.transaction_merchant, latest.txn_type FROM valid s JOIN LATERAL (SELECT c.merchant AS transaction_merchant, c.txn_type FROM transactions c WHERE c.account_id = s.id AND c.txn_time <= s.opened_date ORDER BY c.txn_time DESC, c.id DESC LIMIT 1) latest ON TRUE), joined AS (SELECT a.*, b.city FROM with_last a LEFT JOIN customers b ON a.customer_id = b.id WHERE b.is_active), not_flagged AS (SELECT s.* FROM joined s WHERE NOT EXISTS (SELECT 1 FROM transactions ch WHERE ch.account_id = s.id AND ch.txn_type = 'DEBIT')), with_last_accounts AS (SELECT s.*, latest.transaction_txn_type FROM not_flagged s JOIN LATERAL (SELECT c.txn_type AS transaction_txn_type FROM transactions c WHERE c.account_id = s.id ORDER BY c.txn_time DESC, c.id DESC LIMIT 1) latest ON TRUE), with_dims AS (SELECT src.id, src.customer_id, src.balance, src.account_type_length, src.city, src.transaction_txn_type, b.name, b.segment, b.signup_date FROM with_last_accounts src JOIN customers b ON src.customer_id = b.id), not_flagged_accounts AS (SELECT s.* FROM with_dims s WHERE NOT EXISTS (SELECT 1 FROM transactions ch WHERE ch.account_id = s.id AND ch.account_id = 11)) SELECT DATE_TRUNC('QUARTER', signup_date) AS quarter_start, SIZE(COLLECT_SET(city)) AS num_cities, SUM(CASE WHEN city = 'London' THEN balance ELSE 0 END) AS london_balance, STDDEV_SAMP(balance) AS balance_stddev, SUM(CASE WHEN segment = 'Consumer' THEN account_type_length ELSE 0 END) AS consumer_account_type_length, APPROX_PERCENTILE(balance, 0.5) AS balance_p50, AVG(balance) FILTER (WHERE city = 'Chiang Mai') AS chiang_mai_avg_balance FROM not_flagged_accounts GROUP BY DATE_TRUNC('QUARTER', signup_date) HAVING STDDEV_SAMP(balance) >= 0 ORDER BY balance_stddev NULLS LAST;
